define('taoQtiItem/qtiCreator/widgets/interactions/graphicGapMatchInteraction/states/Correct',['lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Correct', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/GraphicGapMatchInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'taoQtiItem/qtiCommonRenderer/helpers/PciResponse'], function (_, __, stateFactory, Correct, commonRenderer, instructionMgr, PciResponse) {
  'use strict';
  function initCorrectState() {
    var widget = this.widget;
    var interaction = widget.element;
    var response = interaction.getResponseDeclaration();
    var corrects = _.values(response.getCorrect());
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    if (!interaction.paper) {
      return;
    }
    instructionMgr.appendInstruction(interaction, __('Please fill the gap with the correct choices below.'));
    widget.createGapImgs();
    commonRenderer.render.call(interaction.getRenderer(), interaction);
    commonRenderer.setResponse(interaction, PciResponse.serialize(_.invokeMap(corrects, String.prototype.split, ' '), interaction));
    widget.$container.on('responseChange.qti-widget', function (e, data) {
      if (data.response && data.response.list) {
        response.setCorrect(_.map(data.response.list.directedPair, function (pair) {
          return pair.join(' ');
        }));
      }
    });
  }
  function exitCorrectState() {
    var widget = this.widget;
    var interaction = widget.element;
    if (!interaction.paper) {
      return;
    }
    widget.$container.off('responseChange.qti-widget');
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    instructionMgr.removeInstructions(interaction);
    interaction.paper = null;
    interaction.paper = widget.createPaper(_.bind(widget.scaleGapList, widget));
    widget.createChoices();
    widget.createGapImgs();
  }
  return stateFactory.create(Correct, initCorrectState, exitCorrectState);
});
