define('taoQtiItem/controller/creator/index',['jquery', 'lodash', 'module', 'core/logger', 'ui/feedback', 'layout/loading-bar', 'taoQtiItem/qtiCreator/itemCreator', 'taoQtiItem/qtiCreator/editor/areaBroker', 'taoQtiItem/qtiCreator/plugins/loader', 'tpl!taoQtiItem/qtiCreator/tpl/layout/interactionsPanel', 'tpl!taoQtiItem/qtiCreator/tpl/layout/itemPanel', 'tpl!taoQtiItem/qtiCreator/tpl/layout/propertiesPanel'], function ($, _, module, loggerFactory, feedback, loadingBar, itemCreatorFactory, areaBrokerFactory, pluginLoader, interactionsPanelTpl, itemPanelTpl, propertiesPanelTpl) {
  'use strict';
  function loadAreaBroker(config) {
    var $container = $('#item-editor-scope');
    var $wrapper = $('#item-editor-wrapper', $container);
    var panels = [itemPanelTpl, propertiesPanelTpl];
    if (!config || !config.properties || !config.properties.translation) {
      panels.unshift(interactionsPanelTpl);
    }
    panels.forEach(panel => $wrapper.append(panel()));
    return areaBrokerFactory($container, {
      menu: $('.menu', $container),
      menuLeft: $('.menu-left', $container),
      menuRight: $('.menu-right', $container),
      contentCreatorPanel: $('#item-editor-panel', $container),
      editorBar: $('#item-editor-panel .item-editor-bar', $container),
      editorWrapper: $('#item-editor-wrapper', $container),
      title: $('#item-editor-panel .item-editor-bar h1', $container),
      toolbar: $('#item-editor-panel .item-editor-bar #toolbar-top', $container),
      interactionPanel: $('#item-editor-interaction-bar', $container),
      propertyPanel: $('#item-editor-item-widget-bar', $container),
      itemPanel: $('#item-editor-scroll-inner', $container),
      itemPropertyPanel: $('#sidebar-right-item-properties', $container),
      itemCommentsPanel: $('#item-editor-item-comments-bar', $container),
      itemStylePanel: $('#item-style-editor-bar', $container),
      modalContainer: $('#modal-container', $container),
      elementPropertyPanel: $('#item-editor-body-element-property-bar .panel', $container)
    });
  }
  var indexController = {
    start() {
      var config = module.config();
      var logger = loggerFactory('controller/creator');
      function reportError(err) {
        loadingBar.stop();
        logger.error(err);
        if (err instanceof Error) {
          feedback().error(err.message, null, {
            encodeHtml: false
          });
        }
      }
      loadingBar.start();
      if (config) {
        if (config.plugins) {
          config.properties.allowCustomTemplate = config.plugins.some(_ref => {
            var name = _ref.name;
            return name === 'xmlResponseProcessing';
          });
          _.forEach(config.plugins, plugin => {
            if (plugin && plugin.module) {
              pluginLoader.add(plugin);
            }
          });
        }
        if (config.contextPlugins) {
          _.forEach(config.contextPlugins, plugin => {
            if (plugin && plugin.module) {
              if (plugin.exclude) {
                pluginLoader.remove(plugin.module);
              } else {
                pluginLoader.add(plugin);
              }
            }
          });
        }
      }
      pluginLoader.load().then(() => {
        itemCreatorFactory(config, loadAreaBroker(config), pluginLoader.getPlugins()).on('error', reportError).on('success', message => feedback().success(message, null, {
          encodeHtml: false
        })).on('init', function onInit() {
          this.render();
        }).on('ready', () => loadingBar.stop()).init();
      }).catch(reportError);
    }
  };
  return indexController;
});
