define('taoQtiItem/qtiCreator/widgets/interactions/graphicOrderInteraction/Widget',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/interactions/Widget', 'taoQtiItem/qtiCreator/widgets/interactions/graphicInteraction/Widget', 'taoQtiItem/qtiCreator/widgets/interactions/graphicOrderInteraction/states/states', 'taoQtiItem/qtiCommonRenderer/helpers/Graphic'], function ($, _, __, Widget, GraphicWidget, states, GraphicHelper) {
  var GraphicOrderInteractionWidget = _.extend(Widget.clone(), GraphicWidget, {
    initCreator: function initCreator(options) {
      var paper;
      this.baseUrl = options.baseUrl;
      this.choiceForm = options.choiceForm;
      this.registerStates(states);
      Widget.initCreator.call(this);
      paper = this.createPaper(_.bind(this.scaleOrderList, this));
      if (paper) {
        this.element.paper = paper;
        this.createChoices();
        this.renderOrderList();
      }
    },
    destroy: function destroy() {
      var $container = this.$original;
      var $item = $container.parents('.qti-item');
      $item.off("resize.gridEdit.".concat(this.element.serial));
      $(window).off("resize.qti-widget.".concat(this.element.serial));
      $container.off("resize.qti-widget.".concat(this.element.serial));
      Widget.destroy.call(this);
    },
    scaleOrderList: function scaleOrderList(newSize) {
      $('ul.block-listing', this.$original).css('max-width', "".concat(newSize, "px"));
      if (this.element.paper) {
        var interaction = this.element;
        var choices = interaction.getChoices();
        _.forEach(choices, choice => {
          choice.attr('coords', GraphicHelper.qtiCoords(interaction.paper.getById(choice.serial), interaction.paper, interaction.object.attr('width')));
        });
      }
    },
    renderOrderList: function renderOrderList() {
      var interaction = this.element;
      var size = _.size(interaction.getChoices());
      var min = interaction.attr('minChoices');
      var max = interaction.attr('maxChoices');
      var $orderList = $('ul.block-listing', this.$original);
      if (max > 0 && max <= size) {
        size = max;
      } else if (min > 0 && min <= size) {
        size = min;
      }
      $orderList.empty();
      _.times(size, function (index) {
        var position = index + 1;
        var $orderer = $("<li class=\"selectable\" data-number=\"".concat(position, "\">").concat(position, "</li>"));
        if (index === 0) {
          $orderer.addClass('active');
        }
        $orderList.append($orderer);
      });
    }
  });
  return GraphicOrderInteractionWidget;
});
