define('taoQtiItem/qtiCreator/widgets/helpers/comments',[],function () {
  'use strict';

  var autogeneratedCodeStartCommentText = ' autogenerated code, do not edit ';
  var autogeneratedCodeEndCommentText = ' end of autogenerated code ';
  var autogeneratedCodeStartComment = "<!--".concat(autogeneratedCodeStartCommentText, "-->");
  var autogeneratedCodeEndComment = "<!--".concat(autogeneratedCodeEndCommentText, "-->");
  var isCommentNode = (node, text) => node && node.nodeType === Node.COMMENT_NODE && node.textContent && decodeURIComponent(node.textContent).includes(text);
  var findAutogeneratedCodeCommentSibling = (el, siblingDirection) => {
    var commentNode = null;
    var siblingNode = el[siblingDirection];
    var commentsByDirection = {
      previousSibling: autogeneratedCodeStartCommentText,
      nextSibling: autogeneratedCodeEndCommentText
    };
    if (!siblingNode) {
      return null;
    }
    if (siblingNode.textContent && siblingNode.textContent.trim().length === 0) {
      commentNode = findAutogeneratedCodeCommentSibling(siblingNode, siblingDirection);
    } else {
      if (isCommentNode(siblingNode, commentsByDirection[siblingDirection])) {
        commentNode = siblingNode;
      }
    }
    return commentNode;
  };
  var isWrapped = $el => findAutogeneratedCodeCommentSibling($el[0], 'previousSibling') && findAutogeneratedCodeCommentSibling($el[0], 'nextSibling');
  return {
    wrapWithAutogeneratedComment: $el => {
      if (!isWrapped($el)) {
        $el.before(autogeneratedCodeStartComment);
        $el.after(autogeneratedCodeEndComment);
      }
    },
    removeAutogeneratedComments: text => {
      var replaceAll = (str, search, replacement) => str.replace(new RegExp(search, 'g'), replacement);
      text = replaceAll(text, autogeneratedCodeStartComment, '');
      text = replaceAll(text, autogeneratedCodeEndComment, '');
      return text;
    },
    removeAutogeneratedCommentNodes: el => {
      var prevCommentNode = findAutogeneratedCodeCommentSibling(el, 'previousSibling');
      var nextCommentNode = findAutogeneratedCodeCommentSibling(el, 'nextSibling');
      if (prevCommentNode) {
        prevCommentNode.remove();
      }
      if (nextCommentNode) {
        nextCommentNode.remove();
      }
    }
  };
});
