define('taoQtiItem/qtiCreator/widgets/states/Sleep',['taoQtiItem/qtiCreator/widgets/states/factory'], function (stateFactory) {
  'use strict';

  return stateFactory.create('sleep', function () {
    var widget = this.widget,
      $container = this.widget.$container;
    $container.on('mouseenter.sleep', function (e) {
      e.stopPropagation();
      $container.addClass('hover');
      $container.parent().trigger('mouseleave');
    }).on('mouseleave.sleep', function () {
      $container.removeClass('hover');
      $container.parent().trigger('mouseenter');
    });
    if (!widget.isValid()) {
      widget.changeState('invalid');
    }
  }, function () {
    this.widget.$container.removeClass('hover').off('.sleep');
  });
});
