define('taoQtiItem/qtiCreator/plugins/menu/print',['jquery', 'i18n', 'core/request', 'util/url', 'core/plugin', 'ui/hider', 'tpl!taoQtiItem/qtiCreator/plugins/button'], function ($, __, request, urlUtil, pluginFactory, hider, buttonTpl) {
  'use strict';
  var spreadClass = function spreadClass($container, cssClass) {
    $container.parents().each(function initHideOnPrint() {
      $(this).siblings().addClass(cssClass);
    });
  };
  return pluginFactory({
    name: 'print',
    init: function init() {
      var self = this;
      var itemCreator = this.getHost();
      spreadClass(this.getAreaBroker().getItemPanelArea(), 'item-no-print');
      this.$element = $(buttonTpl({
        icon: 'print',
        title: __('Print the item'),
        text: __('Print'),
        cssClass: 'print-trigger'
      })).on('click', function printHandler(e) {
        e.preventDefault();
        var itemConfig = itemCreator.getConfig();
        var itemUri = itemConfig && itemConfig.properties ? itemConfig.properties.uri : null;
        if (itemUri) {
          try {
            request({
              url: urlUtil.route('logFrontendAction', 'Log', 'tao'),
              method: 'POST',
              data: {
                action: 'itemPrintAttempt',
                resourceUri: itemUri
              }
            }).catch(function () {
              return null;
            });
          } catch (e) {}
        }
        window.print();
      });
      this.hide();
      this.disable();
      itemCreator.on('ready', function () {
        self.enable();
      });
    },
    render: function render() {
      var $container = this.getAreaBroker().getMenuArea();
      $container.append(this.$element);
      this.show();
    },
    destroy: function destroy() {
      this.$element.remove();
    },
    enable: function enable() {
      this.$element.removeProp('disabled').removeClass('disabled');
    },
    disable: function disable() {
      this.$element.prop('disabled', true).addClass('disabled');
    },
    show: function show() {
      hider.show(this.$element);
    },
    hide: function hide() {
      hider.hide(this.$element);
    }
  });
});
